diff --git a/src/math.js b/src/math.js
index d0f87bf..4860bb6 100644
--- a/src/math.js
+++ b/src/math.js
@@ -1 +1,2 @@
 export const add = (a, b) => a + b;
+export const clamp = (n, min, max) => Math.min(Math.max(n, min), max);
diff --git a/test/fast/math.test.js b/test/fast/math.test.js
index 749fdaf..00bf1e9 100644
--- a/test/fast/math.test.js
+++ b/test/fast/math.test.js
@@ -1,7 +1,13 @@
 import assert from 'node:assert/strict';
 import test from 'node:test';
-import { add } from '../../src/math.js';
+import { add, clamp } from '../../src/math.js';

 test('add', () => {
   assert.equal(add(1, 2), 3);
 });
+
+test('clamp', () => {
+  assert.equal(clamp(5, 0, 10), 5);
+  assert.equal(clamp(-5, 0, 10), 0);
+  assert.equal(clamp(15, 0, 10), 10);
+});

diff --git a/src/text.js b/src/text.js
index 43ad17d..0a95767 100644
--- a/src/text.js
+++ b/src/text.js
@@ -1 +1 @@
-export const slugify = (s) => s.toLowerCase();
+export const slugify = (s) => s.toLowerCase().trim().replace(/\s+/g, '-');
diff --git a/test/fast/text.test.js b/test/fast/text.test.js
index 1b903b4..226eb97 100644
--- a/test/fast/text.test.js
+++ b/test/fast/text.test.js
@@ -5,3 +5,8 @@ import { slugify } from '../../src/text.js';
 test('slugify lowercases', () => {
   assert.equal(slugify('Hello'), 'hello');
 });
+
+test('slugify replaces whitespace with single dashes', () => {
+  assert.equal(slugify('Hello World'), 'hello-world');
+  assert.equal(slugify('  a   b  '), 'a-b');
+});

