-import { add } from '../../src/math.js';
+import { add, sum } from '../../src/math.js';

 test('add', () => {
   assert.equal(add(1, 2), 3);
 });
+
+test('sum', () => {
+  assert.equal(sum([1, 2, 3]), 6);
+  assert.equal(sum([]), 0);
+});
